package org.com.sharekhan.analysis;
import org.com.sharekhan.config.SecurityConfig;import org.com.sharekhan.service.AdminUserDetailsService;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(CompanyAnalysisController.class) @Import(SecurityConfig.class)
class CompanyAnalysisSecurityTest {
 @Autowired MockMvc mvc;@MockBean CompanyAnalysisService service;@MockBean SavedDailyAnalysis daily;@MockBean AdminUserDetailsService users;
 @Test void userAndAdminCanReadNoStoreRoutes()throws Exception{for(String role:new String[]{"USER","ADMIN"}){mvc.perform(get("/api/stock-analysis/company?symbol=DEMO").with(user("viewer").roles(role))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get("/api/stock-analysis/company/symbols").with(user("viewer").roles(role))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}verify(service,times(2)).report("DEMO",null);}
 @Test void anonymousAndOtherRolesDenied()throws Exception{for(String p:new String[]{"/api/stock-analysis/company","/api/stock-analysis/company/symbols"}){mvc.perform(get(p)).andExpect(status().isUnauthorized());mvc.perform(get(p).with(user("viewer").roles("OTHER"))).andExpect(status().isForbidden());}verifyNoInteractions(service,daily);}
 @Test void calculationRequiresCsrfAndNeverSaves()throws Exception{mvc.perform(post("/api/stock-analysis/company").with(user("viewer").roles("USER")).contentType("application/json").content("{\"symbol\":\"DEMO\"}")).andExpect(status().isForbidden());verifyNoInteractions(service);for(String role:new String[]{"USER","ADMIN"})mvc.perform(post("/api/stock-analysis/company").with(user("viewer").roles(role)).with(csrf()).contentType("application/json").content("{\"symbol\":\"DEMO\"}")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verify(service,times(2)).report(eq("DEMO"),any());}
}
